from itertools import combinations
import z3,time,json

def basis(rows):
    B={}
    for r in rows:
        while r:
            p=r.bit_length()-1
            if p not in B:B[p]=r;break
            r^=B[p]
    return B

def reduce(r,B):
    while r:
        p=r.bit_length()-1
        if p not in B:return r
        r^=B[p]
    return 0

def nulls(rows,n):
    B=basis(rows)
    for j in range(n):
        if j in B:continue
        w=1<<j
        for p,r in sorted(B.items()):
            if (r&w).bit_count()%2:w^=1<<p
        yield w

def components(V,E):
    adj={v:set() for v in V}
    for a,b in E:adj[a].add(b);adj[b].add(a)
    cs=[];left=set(V)
    while left:
        C={left.pop()};todo=list(C)
        while todo:
            v=todo.pop()
            for w in adj[v]&left:left.remove(w);C.add(w);todo.append(w)
        cs.append(C)
    return cs

def cycle_null(edges,triangles):
    ix={e:i for i,e in enumerate(edges)};B={}
    for i,t in enumerate(triangles):
        r=sum(1<<ix[e] for e in combinations(t,2));c=1<<i
        while r:
            p=r.bit_length()-1
            if p not in B:B[p]=(r,c);break
            a,b=B[p];r^=a;c^=b
        if not r:yield c

